"""Render original figures from the JSON generated by the article experiments."""
import argparse
import json
from pathlib import Path

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch

BG, FG, MUTED = '#121b2b', '#edf3fc', '#a9b8cd'
GREEN, RED, BLUE, GOLD = '#64dcc2', '#ff8c9e', '#8cbcff', '#f4c878'


def canvas(title, subtitle):
    fig, ax = plt.subplots(figsize=(12, 6.3), dpi=100)
    fig.patch.set_facecolor(BG)
    ax.set_facecolor(BG)
    ax.set_position([0.08, 0.16, 0.84, 0.58])
    fig.text(0.06, 0.9, title, color=FG, size=32, weight='bold')
    fig.text(0.06, 0.82, subtitle, color=MUTED, size=16)
    ax.tick_params(colors=FG, labelsize=16)
    for spine in ax.spines.values():
        spine.set_visible(False)
    return fig, ax


def save(fig, assets, category, slug):
    folder = assets / category / slug
    folder.mkdir(parents=True, exist_ok=True)
    fig.savefig(folder / 'cover.png', dpi=100, facecolor=BG)
    plt.close(fig)


def box(ax, xy, width, height, text, color):
    ax.add_patch(FancyBboxPatch(xy, width, height, boxstyle='round,pad=0.015',
                              facecolor='#223047', edgecolor=color, linewidth=2))
    ax.text(xy[0]+width/2, xy[1]+height/2, text, ha='center', va='center', color=color, size=19)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--results', type=Path, required=True)
    parser.add_argument('--assets', type=Path, required=True)
    args = parser.parse_args()
    read = lambda name: json.loads((args.results / name).read_text())

    events = read('log/events.json')
    fig, ax = canvas('Log viewer: record vs display', 'Illustration generated from the toy demo’s three actual records')
    ax.set_xlim(-0.02, 1.02); ax.set_ylim(0, 1); ax.axis('off')
    box(ax, (0.0, 0.1), 0.43, 0.8, '\n\n'.join(e['text'].replace('<span style="display:none">', '').replace('</span>', '') for e in events), GREEN)
    ax.annotate('', xy=(0.55, 0.5), xytext=(0.46, 0.5), arrowprops={'arrowstyle':'->', 'color':MUTED, 'lw':3})
    box(ax, (0.57, 0.1), 0.40, 0.8, 'Read input.csv\n\n[hidden by inline CSS]\n\nReport: task complete', RED)
    fig.text(0.08, 0.07, 'Stored JSON', color=GREEN, size=19)
    fig.text(0.57, 0.07, 'HTML illustration, not a screenshot', color=RED, size=14)
    save(fig, args.assets, 'blog', 'agent_log_trust')

    rag = read('rag.json')['results']
    clean = next(r for r in rag if r['payload']=='clean' and r['mode']=='promoted')
    wrong = next(r for r in rag if r['payload']=='false_fact' and r['mode']=='promoted')
    fig, ax = canvas('Retrieval is not verification', 'Actual local Qwen2.5-0.5B answers / fictional vacation policy')
    ax.set_xlim(-0.02, 1.02); ax.set_ylim(0, 1); ax.axis('off')
    for y, label, answer, color in [(0.6,'Document: 28 days',clean['answer'],GREEN),(0.1,'Document: 3 days',wrong['answer'],RED)]:
        box(ax,(0.0,y),0.29,0.28,label,color)
        box(ax,(0.36,y),0.22,0.28,'Retrieved: doc 0',BLUE)
        box(ax,(0.65,y),0.32,0.28,answer.replace(' per year',''),color)
        for start,end in [(0.30,0.35),(0.59,0.64)]:
            ax.annotate('',xy=(end,y+0.14),xytext=(start,y+0.14),arrowprops={'arrowstyle':'->','color':MUTED,'lw':2})
    fig.text(0.06,0.06,'Both instruction attacks failed. Both false-fact runs answered 3 instead of 28.',color=MUTED,size=16)
    save(fig,args.assets,'tips','rag_document_trust')

    threads = read('threads.json')['results']
    fig, ax = canvas('NumPy threads / GIL still on', 'Python 3.15.0 / NumPy 2.5.3 / 8 tasks / median of 7 runs')
    for task,color,label in [('python',GOLD,'Pure Python'),('numpy',GREEN,'NumPy sin + sum')]:
        rows = [r for r in threads if r['task']==task]
        base = rows[0]['median']
        ax.plot([r['workers'] for r in rows],[base/r['median'] for r in rows],'-o',color=color,lw=3,ms=10,label=label)
    ax.set_xticks([1,2,4]); ax.set_xlabel('Worker threads',color=FG,size=17)
    ax.set_ylabel('Speedup vs 1 worker',color=FG,size=17)
    ax.legend(facecolor=BG,labelcolor=FG,fontsize=16)
    ax.grid(axis='y',color='#30405a',alpha=0.5)
    fig.text(0.06,0.035,'GIL enabled: True. This is not a free-threaded vs standard-build comparison.',color=MUTED,size=16)
    save(fig,args.assets,'blog','free_threaded_numpy')

    selection = read('selection.json')
    fig, ax = canvas('Same tasks. Opposite headline.', 'Synthetic selection-bias example / not METR measurements')
    ax.set_position([0.30,0.16,0.62,0.58])
    labels = ['All 100 tasks','50 selected tasks']
    changes = [selection[k]['time_change_percent'] for k in ['all_tasks','submitted_tasks']]
    ax.barh(labels,changes,color=[GREEN,RED],height=0.5)
    ax.axvline(0,color=FG,lw=1)
    ax.set_xlim(-50,25); ax.invert_yaxis()
    for i,val in enumerate(changes):
        ax.text(val+(-1 if val<0 else 1),i,f'{val:+.1f}%',ha='right' if val<0 else 'left',va='center',color=FG,size=24)
    ax.set_xlabel('Change in total completion time with assistance (%)',color=FG,size=15)
    save(fig,args.assets,'ds','ai_productivity_selection')

    tabular = read('tabular.json')['results']
    fig, ax = canvas('Same model. Different split.', 'One LightGBM baseline / synthetic repeated-group data / not TabPFN results')
    ax.bar([r['split'] for r in tabular],[r['auc'] for r in tabular],color=[BLUE,GOLD],width=0.5)
    ax.set_ylim(0,1.15); ax.set_ylabel('Test ROC AUC',color=FG,size=18)
    ax.axhline(0.5,color=MUTED,ls='--',lw=1)
    for i,row in enumerate(tabular):
        ax.text(i,row['auc']+0.03,f"{row['auc']:.4f}",ha='center',color=FG,size=24)
        ax.text(i,0.1,f"Shared groups: {row['shared_groups']}",ha='center',color=BG,size=17)
    save(fig,args.assets,'blog','tabpfn_lightgbm_evaluation')


if __name__=='__main__':
    main()
